<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('withdrawals.view');$id=filter_var(input('id'),FILTER_VALIDATE_INT);if(!$id){http_response_code(404);exit('Not found');}if(is_post()){verify_csrf();$target=strtoupper((string)input('status'));if($target==='REJECTED')require_permission('withdrawals.reject');else require_permission('withdrawals.approve');try{transition_withdrawal($id,$target,trim((string)input('reason')),(int)admin()['id']);flash('success','Withdrawal moved to '.$target.'.');}catch(Throwable $e){flash('error',$e instanceof PDOException?'Could not process withdrawal.':$e->getMessage());}redirect('/admin/withdrawals/view.php?id='.$id);}
$stmt=db()->prepare('SELECT w.*,u.name,u.email,u.mobile,u.status user_status,u.risk_level user_risk,wa.balance,d.device_name,d.device_id,d.ip_address device_ip,d.last_active_at FROM withdrawals w JOIN users u ON u.id=w.user_id JOIN wallets wa ON wa.id=w.wallet_id LEFT JOIN user_devices d ON d.user_id=u.id AND d.status="ACTIVE" WHERE w.id=? ORDER BY d.last_active_at DESC LIMIT 1');$stmt->execute([$id]);$wd=$stmt->fetch();if(!$wd){http_response_code(404);exit('Not found');}$tx=db()->prepare('SELECT * FROM wallet_transactions WHERE user_id=? ORDER BY id DESC LIMIT 8');$tx->execute([$wd['user_id']]);$events=db()->prepare('SELECT * FROM security_events WHERE user_id=? ORDER BY id DESC LIMIT 8');$events->execute([$wd['user_id']]);$attempts=db()->prepare('SELECT * FROM withdrawal_attempts WHERE withdrawal_id=? ORDER BY id DESC LIMIT 10');$attempts->execute([$id]);$pageTitle=$wd['withdrawal_id'];$pageSubtitle='Withdrawal review';require APP_ROOT.'/includes/header.php';?>
<div class="grid detail-grid"><section class="panel"><div class="panel-head"><h2>Request</h2><span class="badge <?=strtolower(e($wd['status']))?>"><?=e($wd['status'])?></span></div><div class="kv"><span>Amount</span><strong><?=money($wd['amount'])?></strong></div><div class="kv"><span>Available balance</span><strong><?=money($wd['balance'])?></strong></div><div class="kv"><span>Payment method</span><strong><?=e($wd['payment_method'])?></strong></div><div class="kv"><span>Account</span><strong><?=e($wd['payment_account_masked']??'—')?></strong></div><div class="kv"><span>Request risk</span><strong class="risk <?=strtolower(e($wd['risk_level']))?>"><?=e($wd['risk_level'])?></strong></div></section><section class="panel"><div class="panel-head"><h2>Customer & device</h2><a href="<?=e(app_url('/admin/users/view.php?id='.$wd['user_id']))?>">Open profile →</a></div><div class="kv"><span>Name</span><strong><?=e($wd['name'])?></strong></div><div class="kv"><span>Account status</span><strong><?=e($wd['user_status'])?></strong></div><div class="kv"><span>User risk</span><strong><?=e($wd['user_risk'])?></strong></div><div class="kv"><span>Active device</span><strong><?=e($wd['device_name']??'—')?> · <?=e($wd['device_ip']??'—')?></strong></div></section></div>
<?php $actions=['PENDING'=>['UNDER_REVIEW','REJECTED','CANCELLED'],'UNDER_REVIEW'=>['APPROVED','REJECTED'],'APPROVED'=>['PROCESSING'],'PROCESSING'=>['PAID']][$wd['status']]??[];if($actions):?><section class="panel"><h2>Take action</h2><form method="post" class="form-grid" data-confirm="Confirm this withdrawal status change? Financial actions cannot be silently undone."><?=csrf_field()?><div class="field"><label>Next status</label><select name="status" required><?php foreach($actions as $a):if(($a==='REJECTED'&&!can('withdrawals.reject'))||($a!=='REJECTED'&&!can('withdrawals.approve')))continue;?><option><?=e($a)?></option><?php endforeach?></select></div><div class="field"><label>Reason / review note</label><input name="reason" maxlength="500" placeholder="Required when rejecting"></div><div class="field full"><button class="btn">Confirm transition</button></div></form></section><?php endif?>
<div class="grid detail-grid"><section class="panel"><h2>Recent transactions</h2><?php foreach($tx->fetchAll() as $t):?><div class="kv"><span><?=e($t['type'])?></span><strong><?=money($t['amount'])?> · <?=e($t['created_at'])?></strong></div><?php endforeach?></section><section class="panel"><h2>Security indicators</h2><?php foreach($events->fetchAll() as $ev):?><div class="kv"><span class="risk <?=strtolower(e($ev['risk_level']))?>"><?=e($ev['risk_level'])?></span><strong><?=e($ev['event_type'])?> · <?=e($ev['created_at'])?></strong></div><?php endforeach?></section></div>
<section class="panel"><h2>Processing history</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Outcome</th><th>IP</th><th>Reason</th></tr></thead><tbody><?php foreach($attempts->fetchAll() as $a):?><tr><td><?=e($a['created_at'])?></td><td><?=e($a['outcome'])?></td><td><?=e($a['ip_address']??'—')?></td><td><?=e($a['reason']??'—')?></td></tr><?php endforeach?></tbody></table></div></section><?php require APP_ROOT.'/includes/footer.php';
